// QA joint for identify-match-override (box 4.1): the identify PUT against
// the REAL graph — the composed world, the shikimori subprocess, and the stub
// upstream. The PUT runs over the api route via a second httptest server over
// the SAME world, its identify closure mirrored in miniature per the harness
// contract (cmd/mellifera is package main). Scenario: after the organic
// title-search leg lands row A on anime 4242, the PUT re-anchors row A to a
// DIFFERENT anime the stub carries ONLY under its by-id endpoint — the
// re-derive must fetch GET /api/animes/{picked_id} (never a fresh search —
// no search list mentions the picked id, so a title-search fallback could
// never land these facts), the fresh namespace must reflect the picked
// anime's facts, and the served series must keep its display name (the
// shikimori strip never touches the parser namespace the seriesName chain
// reads).
package itest

import (
	"context"
	"net/http"
	"net/http/httptest"
	"strconv"
	"testing"

	"github.com/mellifera/mellifera/internal/api"
)

// qaIdentifyPickedID is the picked anime's upstream id — absent from every
// search list (only the by-id endpoint serves it), which is what makes the
// anchored re-derive provable.
const qaIdentifyPickedID = 4253

// qaIdentifyWantPicked is the picked anime's fixture projected into the
// shared namespace expectation. Kind stays "tv" (the namespace contract the
// shared assertion pins); every other fact differs from row A's on its face.
var qaIdentifyWantPicked = qaShikWant{
	id:       qaIdentifyPickedID,
	episodes: 13,
	romaji:   "Cowboy Bebop Remixed",
	russian:  "Ковбой Бибоп Ремикс",
	aired:    "2001-09-01",
	score:    7.7,
}

// TestIdentifyMatchJoint is the Tier-1 joint round trip of the identify
// re-anchor: real PUT route → real queue → real shikimori subprocess → stub
// upstream.
func TestIdentifyMatchJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("identify joint: skips under -short (builds binaries + subprocesses)")
	}
	j := qaShikStartJoint(t)

	// The stub carries the picked anime under its by-id endpoint ONLY. The
	// map is package state shared with TestShikimoriJoint (this package
	// never runs tests in parallel; the added key is one that test never
	// looks up).
	qaShikByID[strconv.Itoa(qaIdentifyPickedID)] = qaShikAnime(
		qaIdentifyWantPicked.id, qaIdentifyWantPicked.romaji, qaIdentifyWantPicked.russian,
		"tv", qaIdentifyWantPicked.episodes, qaIdentifyWantPicked.aired,
		strconv.FormatFloat(qaIdentifyWantPicked.score, 'f', 1, 64))

	// --- leg 1: the organic title-search baseline (the pre-identify state) ---
	if res := pbScanLibrary(t, j.w, j.lib); res.Persisted == 0 {
		t.Fatalf("scan persisted nothing: %+v", res)
	}
	seriesA := qaShikAwaitNamespace(t, j, qaShikDirA)
	qaShikAssertNamespace(t, j, seriesA, qaShikWantA)

	// The served display name BEFORE the identify — the seriesName chain
	// reads the parser namespace, which identify never touches.
	before := qaIdentifyDisplayName(t, j, seriesA)
	if before == "" {
		t.Fatalf("series %s: empty display_name before the identify (nothing to keep)", seriesA)
	}

	// --- the identify PUT over the real api route ---
	// The shim serves the SAME world's store with the identify closure wired
	// the main.go shape, INCLUDING its context rule (main.go
	// INV-context-shared): the queued re-derivation must outlive the HTTP
	// request, so the closure substitutes the joint's own context.
	shim := api.New(api.Deps{
		AdminToken: j.w.token,
		Store:      j.w.st,
		IdentifySeries: func(ctx context.Context, seriesID, pluginID, externalID string) (bool, int, int, error) {
			return j.q.IdentifySeries(context.WithoutCancel(ctx), seriesID, pluginID, externalID)
		},
	})
	identifySrv := httptest.NewServer(shim)
	t.Cleanup(identifySrv.Close)

	var result struct {
		Queued   bool `json:"queued"`
		Stripped int  `json:"stripped"`
		Deferred int  `json:"deferred"`
	}
	pick := map[string]string{"source_id": "shikimori", "external_id": strconv.Itoa(qaIdentifyPickedID)}
	if status := doRequest(t, j.w.client, http.MethodPut,
		identifySrv.URL+"/api/v1/series/"+seriesA+"/identify", j.w.token, pick, &result); status != http.StatusAccepted {
		t.Fatalf("identify PUT: HTTP %d, want 202", status)
	}
	if !result.Queued || result.Stripped != 1 || result.Deferred != 0 {
		t.Fatalf("identify PUT = %+v, want queued=true stripped=1 deferred=0 (row A carried the namespace, nothing in cooldown)", result)
	}

	// --- the re-derive: the anchor drives a by-id fetch, never a search ---
	fresh := qaShikAwaitNamespace(t, j, qaShikDirA)
	if fresh != seriesA {
		t.Fatalf("re-derive landed on row %s, want the identified row %s", fresh, seriesA)
	}
	// The full namespace contract on the picked facts — including
	// identifiers.shikimori_id == the picked id (the anchor the write put
	// there and the strip preserved).
	qaShikAssertNamespace(t, j, fresh, qaIdentifyWantPicked)
	// The stub saw leg 1's 2 search requests, then EXACTLY the anchored
	// quad appended: by-id + /roles + /episodes + the GraphQL poster POST
	// for the picked id — the /episodes companion sanctioned by openspec
	// change episode-titles, the GraphQL poster by the artwork fallback
	// (leg 1 fetches by search only — the first by-id fetches ever recorded
	// are the identify leg's). A search request here breaks either the
	// total or the tail's by-id paths.
	qaShikAssertAnchoredLeg(t, j, 2+4, qaIdentifyPickedID)

	// --- the served display name survives ---
	if after := qaIdentifyDisplayName(t, j, fresh); after != before {
		t.Errorf("display_name changed across the identify: %q → %q (the source strip never touches the parser namespace)", before, after)
	}
}

// qaIdentifyDisplayName fetches one series' server-composed display_name —
// the wire field the SPA's seriesDisplayTitle reads.
func qaIdentifyDisplayName(t *testing.T, j *qaShikJoint, seriesID string) string {
	t.Helper()
	var resp struct {
		Series struct {
			DisplayName string `json:"display_name"`
		} `json:"series"`
		Error struct {
			Code string `json:"code"`
		} `json:"error"`
	}
	status := doRequest(t, j.w.client, http.MethodGet,
		j.w.baseURL+"/api/v1/series/"+seriesID, j.w.token, nil, &resp)
	if status != http.StatusOK {
		t.Fatalf("GET /series/%s: HTTP %d (%s)", seriesID, status, resp.Error.Code)
	}
	return resp.Series.DisplayName
}
